  --text-primary: #ffffff;
  --text-secondary: #b3b3b3;
  --accent-color: #bb86fc;
  --accent-hover: #9965f4;
  --focus-ring: #03dac6;
  --error-color: #cf6679;
  --border-color: #333333;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* Accessibility: Focus management & Screen Reader Only */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
