const { useState } = React;

// Sample Data
const products = [
  { id: '1', name: 'Midnight Obsidian Watch', price: '$249', originalPrice: null, isDeal: false, image: 'https://images.unsplash.com/photo-1524805444758-089113d48a6d?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80' },
  { id: '2', name: 'Stealth Black Backpack', price: '$129', originalPrice: null, isDeal: false, image: 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80' },
  { id: '3', name: 'Lunar Wireless Headphones', price: '$199', originalPrice: null, isDeal: false, image: 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80' },
  { id: '4', name: 'Carbon Fiber Wallet', price: '$49', originalPrice: null, isDeal: false, image: 'https://images.unsplash.com/photo-1627123424574-724758594e93?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80' }
];

const deals = [
  { id: '5', name: 'Eclipse Aviator Sunglasses', price: '$79', originalPrice: '$129', isDeal: true, image: 'https://images.unsplash.com/photo-1511499767150-a48a237f0083?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80' },
  { id: '6', name: 'Onyx Smart Ring', price: '$149', originalPrice: '$199', isDeal: true, image: 'https://images.unsplash.com/photo-1599643478524-fb524458f4a7?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80' },
