        </p>
        <a href="/collection/midnight" className="btn-primary">Read the Story</a>
      </div>
    </div>
  </section>
);

const Footer = () => (
  <footer className="site-footer">
    <div className="container">
      <nav aria-label="Footer" className="footer-nav">
        <div className="footer-section">
          <h2>Shop</h2>
          <ul>
            <li><a href="/new">New Arrivals</a></li>
            <li><a href="/best-sellers">Best Sellers</a></li>
            <li><a href="/accessories">Accessories</a></li>
          </ul>
        </div>
        <div className="footer-section">
          <h2>Support</h2>
          <ul>
            <li><a href="/faq">FAQ</a></li>
            <li><a href="/shipping">Shipping & Returns</a></li>
            <li><a href="/contact">Contact Us</a></li>
          </ul>
        </div>
        <div className="footer-section">
          <h2>About</h2>
          <ul>
            <li><a href="/our-story">Our Story</a></li>
            <li><a href="/sustainability">Sustainability</a></li>
            <li><a href="/careers">Careers</a></li>
          </ul>
        </div>
      </nav>
      <div className="footer-bottom">
        <p>&copy; {new Date().getFullYear()} Lumina Retail. All rights reserved.</p>
      </div>
    </div>
  </footer>
);

const App = () => {
  return (
    <React.Fragment>
      <a href="#maincontent" className="sr-only skip-link">Skip to main content</a>
      <Header />
      <main id="maincontent" tabIndex="-1" className="main-content">
        <Hero />
        <ProductSection id="featured" title="Featured Products" products={products} />
        <ProductSection id="deals" title="Today's Deals" products={deals} />
        <Editorial />
      </main>
      <Footer />
    </React.Fragment>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);

</script>
