const ProductCard = ({ product }) => {
  const { id, name, price, originalPrice, isDeal, image } = product;

  const handleAddToCart = (e) => {
    // Prevent default link behavior if clicking the button inside an article
    e.preventDefault();
    alert(`Added ${name} to cart.`);
  };

  return (
    <article className="product-card">
      <a href={`/product/${id}`} className="product-image-link" aria-hidden="true" tabIndex="-1">
        <div className="product-image-container">
          <img src={image} alt="" className="product-image" loading="lazy" />
          {isDeal && <span className="deal-badge">Sale</span>}
        </div>
      </a>
      <div className="product-details">
        <h3 className="product-title">
          <a href={`/product/${id}`} className="product-link">{name}</a>
        </h3>
        <p className="product-price">
          {isDeal ? (
            <span>
              <span className="sr-only">Sale price: </span>{price}{' '}
              <span className="sr-only">Original price: </span><s className="original-price">{originalPrice}</s>
            </span>
          ) : (
            price
          )}
        </p>
        <button 
          type="button" 
          className="add-to-cart-btn" 
          aria-label={`Add to cart: ${name}`}
          onClick={handleAddToCart}
        >
          Add to cart
        </button>
      </div>
    </article>
  );
};

